const assets={"/": ["text/html; charset=utf-8", ""], "/icon.png": ["image/png", ""], "/large.png": ["image/png", ""], "/sw.js": ["text/javascript", "c2VsZi5hZGRFdmVudExpc3RlbmVyKCdmZXRjaCcsKCk9Pnt9KTsK"], "/manifest.webmanifest": ["application/manifest+json", ""]};
async function broadcast(url,bucket,user,data){
 if(!user)return error('Sign in first',401);
 const [, , ,id,part]=url.pathname.split('/');
 if(!id){
  if(data){
   if(typeof data.title!=='string'||!data.title.trim()||data.title.length>100)return error('Enter a title',400);
   const id=crypto.randomUUID(),record={id,title:data.title.trim(),owner:user,until:Date.now()+90000,last:-1};
   await bucket.put('live/'+id,JSON.stringify(record));return json(record,201);
  }
  const rows=await bucket.list({prefix:'live/',limit:1000});
  const records=await Promise.all(rows.objects.map(x=>loadRecord(bucket,x.key)));
  return json(records.filter(x=>x.until>Date.now()));
 }
 if(!/^[a-f0-9-]{36}$/.test(id))return error('Invalid stream',400);
 const key='live/'+id,object=await bucket.get(key);if(!object)return error('Stream unavailable',404);
 const live=await object.json();
 if(!data){
  if(!part)return json(live);
  if(!/^\d{1,7}$/.test(part)||live.until<Date.now())return error('Stream ended',410);
  const clip=await bucket.get('segments/'+id+'/'+part);if(!clip)return error('Waiting for video',404);
  return new Response(clip.body,{headers:{'Content-Type':clip.httpMetadata.contentType,'Cache-Control':'private, no-store'}});
 }
 if(user!==live.owner)return error('Only the broadcaster can change this stream',403);
 if(live.until<Date.now())return error('Stream ended',410);
 if(data.end)live.until=0;
 else{
  if(!Number.isInteger(data.index)||data.index!==live.last+1||typeof data.video!=='string'||data.video.length>4000000||!['video/webm','video/mp4'].includes(data.type))return error('Invalid stream segment',400);
  await bucket.put('segments/'+id+'/'+data.index,bytes(data.video),{httpMetadata:{contentType:data.type}});
  live.last=data.index;live.until=Date.now()+90000;
 }
 if(!await bucket.put(key,JSON.stringify(live),{onlyIf:{etagMatches:object.etag}}))return error('Stream changed',409);
 if(live.last>=5&&!data.end)await bucket.delete('segments/'+id+'/'+(live.last-5));
 return json(live);
}
async function messages(url,store,user,data) {
 if(!user)return error('Sign in first',401);
 const [, , ,peer,verb]=url.pathname.split('/');
 if(!peer){
  if(data)return error('Choose a recipient',400);
  const rows=await store.list({prefix:'inbox/'+user+'/',limit:1000});
  return json(rows.objects.map(x=>x.key.split('/').pop()));
 }
 if(!/^[a-z0-9_]{2,32}$/.test(peer)||peer===user||!await store.head('users/'+peer))return error('Choose another registered handle',404);
 const pair=[user,peer].sort().join('/');
 const prefix='chat/'+pair+'/';
 if(verb==='call'){
  const key='call/'+pair;
  const record=await store.get(key);
  const current=record?await record.json():null;
  const active=current&&current.until>Date.now();
  if(!data)return json(active?current:null);
  let next;
  if(data.action==='offer'){
   if(active)return error('A call is already active',409);
   if(!['voice','video'].includes(data.mode)||typeof data.sdp!=='string'||data.sdp.length>90000)return error('Invalid offer',400);
   next={id:crypto.randomUUID(),from:user,to:peer,mode:data.mode,offer:data.sdp,until:Date.now()+90000};
  }else{
   if(!active||current.id!==data.id)return error('Call expired',409);
   if(data.action==='answer'&&current.to===user&&!current.answer&&typeof data.sdp==='string'&&data.sdp.length<=90000)next={...current,answer:data.sdp,until:Date.now()+3600000};
   else if(data.action==='end')next={id:current.id,until:0};
   else return error('Invalid call action',400);
  }
  const condition=record?{etagMatches:record.etag}:{etagDoesNotMatch:'*'};
  if(!await store.put(key,JSON.stringify(next),{onlyIf:condition}))return error('Call changed. Try again.',409);
  await Promise.all([store.put('inbox/'+user+'/'+peer,''),store.put('inbox/'+peer+'/'+user,'')]);
  return json(next);
 }
 if(verb)return error('Unknown action',404);
 if(data){
  if(typeof data.body!=='string'||!data.body.trim()||data.body.length>2200)return error('Enter a message up to 2,200 characters',400);
  if(!/^[a-f0-9-]{36}$/.test(data.id||''))return error('Message ID required',400);
  await Promise.all([store.put('inbox/'+user+'/'+peer,''),store.put('inbox/'+peer+'/'+user,'')]);
  await store.put(prefix+user+'-'+data.id,JSON.stringify({name:user,body:data.body.trim(),at:Date.now()}),{onlyIf:{etagDoesNotMatch:'*'}});
  return json({},201);
 }
 const list=await store.list({prefix,limit:1000});
 const rows=await Promise.all(list.objects.map(x=>loadRecord(store,x.key)));
 return json(rows.sort((a,b)=>a.at-b.at));
}
const kinds=['pages','groups','market'];
async function loadRecord(bucket,key){const object=await bucket.get(key);return object?object.json():null}
async function community(req,url,bucket,user,data){
 const parts=url.pathname.split('/').slice(2),[kind,id,op]=parts;
 if(!user)return error('Sign in first',401);
 if(kind==='profile'){
  const who=id||user;
  if(!/^[a-z0-9_]{2,32}$/.test(who))return error('Invalid handle',400);
  if(data){
   if(who!==user)return error('Forbidden',403);
   if(!['displayName','color','fade','logo','wall','song'].includes(data.key))return error('Unknown setting',400);
   const v=data.value;
   if(typeof v!=='string')return error('Invalid setting',400);
   const valid={displayName:()=>v.length<=40,color:()=>/^#[0-9a-f]{6}$/i.test(v),fade:()=>/^\d{1,3}$/.test(v)&&Number(v)<=100,logo:()=>/^data:image\/(png|jpeg|webp|gif);base64,/.test(v),wall:()=>/^data:image\/(png|jpeg|webp|gif);base64,/.test(v),song:()=>/^data:audio\/(mpeg|ogg|wav|mp4);base64,/.test(v)};
   if(!valid[data.key]()||v.length>5300000)return error('Unsupported file or setting',400);
   await bucket.put('theme/'+user+'/'+data.key,JSON.stringify(v));return json({});
  }
  const keys=who===user?['displayName','color','fade','logo','wall','song']:['displayName','color','wall','song'];
  return json(Object.fromEntries(await Promise.all(keys.map(async key=>[key,await loadRecord(bucket,'theme/'+who+'/'+key)]))));
 }
 if(!kinds.includes(kind))return error('Unknown section',404);
 const prefix='community/'+kind+'/';
 if(!id){
  if(data){
   if(typeof data.name!=='string'||!data.name.trim()||data.name.length>160||typeof data.description!=='string'||!data.description.trim()||data.description.length>1000)return error('Enter a name and description',400);
   if(kind==='market'&&(!Number.isFinite(data.price)||data.price<0))return error('Enter a valid price',400);
   const key=crypto.randomUUID();
   await bucket.put(prefix+key,JSON.stringify({id:key,name:data.name.trim(),description:data.description.trim(),price:data.price,owner:user,created:Date.now()}));return json({id:key},201);
  }
  const items=await bucket.list({prefix,limit:1000});
  const records=await Promise.all(items.objects.map(async o=>{const item=await loadRecord(bucket,o.key);return {...item,own:item.owner===user,active:!!await bucket.head('member/'+user+'/'+item.id)}}));
  return json(records.sort((a,b)=>b.created-a.created));
 }
 if(!/^[a-f0-9-]{36}$/.test(id)||!await bucket.head(prefix+id))return error('Entry unavailable',404);
 const member='member/'+user+'/'+id;
 if(op==='membership'&&data&&typeof data.active==='boolean'){
  if(data.active)await bucket.put(member,'1');else await bucket.delete(member);return json({});
 }
 if(kind==='groups'&&op==='discussion'){
  const item=await loadRecord(bucket,prefix+id);
  if(item.owner!==user&&!await bucket.head(member))return error('Join the group first',403);
  const thread='discussion/'+id+'/';
  if(data){
   if(typeof data.body!=='string'||!data.body.trim()||data.body.length>1000)return error('Enter a message',400);
   await bucket.put(thread+(9999999999999-Date.now())+'-'+crypto.randomUUID(),JSON.stringify({name:user,body:data.body.trim()}));return json({},201);
  }
  const list=await bucket.list({prefix:thread,limit:50});return json(await Promise.all(list.objects.map(o=>loadRecord(bucket,o.key))));
 }
 return error('Unknown action',404);
}
const bytes=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
const json=(data,status=200,headers={})=>Response.json(data,{status,headers:{"Cache-Control":"no-store",...headers}});
const error=(message,status)=>json({error:message},status);
async function digest(password,salt){
 const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);
 const value=await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',iterations:100000,salt:new TextEncoder().encode(salt)},key,256);
 return btoa(String.fromCharCode(...new Uint8Array(value)));
}
export default {async fetch(req,env){
 const url=new URL(req.url),p=url.pathname,asset=Object.hasOwn(assets,p)&&assets[p];
 if(asset&&req.method==='GET')return new Response(bytes(asset[1]),{headers:{'Content-Type':asset[0]}});
 const bucket=env.BUCKET;
 const cookie=(req.headers.get('Cookie')||'').match(/(?:^|;\s*)ms=([a-f0-9-]{36})(?:;|$)/);
 const session=cookie&&await bucket.get('sessions/'+cookie[1]);
 const user=session&&Number(session.customMetadata?.expires)>Date.now()?await session.text():null;
 if(p==='/api/me')return json({name:user});
 const livePath=/^\/api\/live(?:\/|$)/.test(p);
 if(livePath&&req.method==='GET')return broadcast(url,bucket,user,null);
 const chatPath=/^\/api\/messages(?:\/|$)/.test(p);
 if(chatPath&&req.method==='GET')return messages(url,bucket,user,null);
 const communityPath=/^\/api\/(profile|pages|groups|market)(?:\/|$)/.test(p);
 if(communityPath&&req.method==='GET')return community(req,url,bucket,user,null);
 if(req.method==='POST'){
 if(req.headers.get('Origin')!==url.origin||req.headers.get('Content-Type')!=='application/json')return error('Invalid request',403);
 if(Number(req.headers.get('Content-Length'))>6000000)return error('File too large',413);
 const data=await req.json();
 if(livePath)return broadcast(url,bucket,user,data);
 if(chatPath)return messages(url,bucket,user,data);
 if(communityPath)return community(req,url,bucket,user,data);
 if(p==='/api/login'||p==='/api/register'){
 const name=String(data.name||'').trim().toLowerCase(),pass=String(data.password||'');
 if(!/^[a-z0-9_]{2,32}$/.test(name)||pass.length<8||pass.length>128)return error('Use a 2–32 character handle and an 8–128 character password.',400);
 const path='users/'+name;
 if(p.endsWith('register')){
 const salt=crypto.randomUUID(),hash=await digest(pass,salt);
 if(!await bucket.put(path,JSON.stringify({salt,hash}),{onlyIf:{etagDoesNotMatch:'*'}}))return error('Handle already taken',409);
 }else{
 const account=await bucket.get(path),record=account&&await account.json();
 if(!record||record.hash!==await digest(pass,record.salt))return error('Check your handle and password',403);
 }
 const id=crypto.randomUUID();
 await bucket.put('sessions/'+id,name,{customMetadata:{expires:String(Date.now()+604800000)}});
 return json({name},200,{'Set-Cookie':'ms='+id+'; Path=/; Secure; HttpOnly; SameSite=Lax; Max-Age=604800'});
 }
 if(!user)return error('Sign in first',401);
 if(p==='/api/logout'){await bucket.delete('sessions/'+cookie[1]);return json({},200,{'Set-Cookie':'ms=; Path=/; Secure; Max-Age=0'});}
 if(p==='/api/post'){
 const body=data.body,media=data.media;
 if(typeof body!=='string'||body.length>2200||typeof media!=='string'||(!body.trim()&&!media))return error('Add a caption or file',400);
 const id=String(9999999999999-Date.now())+'-'+crypto.randomUUID();
 if(media){
 const match=/^data:(image\/(?:jpeg|png|gif|webp)|video\/(?:mp4|webm));base64,/.exec(media);
 if(!match||media.length>5333400)return error('Choose a supported photo or video under 4 MB',400);
 await bucket.put('media/'+id,bytes(media.slice(match[0].length)),{httpMetadata:{contentType:match[1]}});
 }
 await bucket.put('posts/'+id,JSON.stringify({id,name:user,body,attached:!!media}));
 return json({},201);
 }}
 if(!user)return error('Sign in first',401);
 if(p==='/api/feed'){const list=await bucket.list({prefix:'posts/',limit:40});return json(await Promise.all(list.objects.map(async o=>(await bucket.get(o.key)).json())))}
 if(/^\/media\/[0-9a-f-]+$/.test(p)){const file=await bucket.get(p.slice(1));if(file)return new Response(file.body,{headers:{'Content-Type':file.httpMetadata.contentType,'X-Content-Type-Options':'nosniff','Cache-Control':'private, no-store'}})}
 return error('Not found',404);
}};
